-- نتیجه‌ی «آمار هر قطعه» (NDVI) برای جدول parcels، از محیط نمایشی کتاب؛ برای تمرین فصل‌های ۳۶ و ۳۷ بدون نیاز به دریافت تصویر.
CREATE TABLE ndvi_parcels (feature_id text NOT NULL, scene_date date NOT NULL, scene text NOT NULL, mean double precision, median double precision,
  min double precision, max double precision, std double precision, valid_pct real, n_pixels int, n_valid int, PRIMARY KEY (feature_id, scene_date, scene));
CREATE INDEX ON ndvi_parcels (scene_date);
